window.HOEREN_TESTS[30] = {"id":"beim-zahnarzt","name":"Beim Zahnarzt","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Frau Klein, hier ist die Zahnarztpraxis Dr. Bauer, ihr Termin morgen um 10 Uhr fällt leider aus, weil Doktor Bauer krank ist. Ein Termin erst nächste Woche ist zu spät, das verstehen wir. Wir können Ihnen aber Freitag um 9 Uhr oder Montag um 15 Uhr anbieten. Bitte rufen Sie zurück, was besser passt.","gender":"f","q":"Wann sind alternative Termine möglich?","opts":["Morgen um 10 Uhr.","Freitag um 9 oder Montag um 15.","Erst nächste Woche."],"correct":1},{"transcript":"Achtung, liebe Patienten: Wegen Renovierung machen wir unsere Zahnarztpraxis vom 15. bis 20. April zu, bitte gehen Sie in dieser Zeit trotzdem nicht in die Praxis, wir sind wirklich nicht da. Das Krankenhaus ist nur für schwere Unfälle. Für normale Notfälle gehen Sie bitte zu Dr. Lehmann in der Hauptstraße 22, ab 21. April sind wir wieder da.","gender":"m","q":"Wohin gehen Patienten bei Notfall?","opts":["Trotzdem in die eigene Praxis.","Zu Dr. Lehmann.","Ins Krankenhaus."],"correct":1},{"transcript":"Hi Schatz, hier ist Mama. Der Zahnarzt hat angerufen, die Zahnprothese ist fertig. Sie ist heute zur Abholung bereit, oder spätestens morgen. Bitte hol sie ab, ich bin in der Arbeit. 280 Euro musst du bar bezahlen. Mit Karte geht das nicht, und mit dem Handy auch nicht, weil die Praxis so alt ist.","gender":"f","q":"Wie soll der Sohn zahlen?","opts":["Bar.","Mit Karte.","Mit dem Handy."],"correct":0},{"transcript":"Liebe Patienten, eine wichtige Erinnerung: Wer einen Termin für eine Zahnreinigung hat, bitte zwei Stunden vorher nichts essen. Wasser ist erlaubt, kaffee mit Milch oder süßen Tee trinken Sie bitte nicht, das ist zu süß. Auch Bonbons mit Zucker nicht. Vielen Dank für Ihre Mitarbeit.","gender":"m","q":"Was darf man vor der Zahnreinigung trinken?","opts":["Kaffee mit Milch.","Süßen Tee.","Wasser."],"correct":2},{"transcript":"Hallo Lukas, hier ist die Zahnarzthelferin. Also, dein Termin nächste Woche: Der Doktor ist krank geworden. Wir verschieben deinen Termin von Dienstag um 16 Uhr auf Mittwoch, gleiche Uhrzeit, 16 Uhr. Donnerstag um 16 Uhr geht bei uns nicht, der Kalender ist voll. Falls Mittwoch nicht klappt, schreib uns bitte.","gender":"f","q":"Wann ist der neue Termin?","opts":["Mittwoch um 16 Uhr.","Dienstag um 16 Uhr.","Donnerstag um 16 Uhr."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer macht was beim Zahnarzt? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Dieter","gender":"m","text":"Hallo! Der Zahnarzt hat diese Woche mehrere Termine für uns."},{"speaker":"Monika","gender":"f","text":"Ich habe den Kalender an den Kühlschrank gehängt."},{"speaker":"Dieter","gender":"m","text":"Ich bekomme am Dienstag eine Zahnreinigung."},{"speaker":"Monika","gender":"f","text":"Danach fühlt sich alles frisch an, Dieter. Das tut dir gut."},{"speaker":"Dieter","gender":"m","text":"Will noch jemand die Zähne bleichen lassen?"},{"speaker":"Monika","gender":"f","text":"Nein. Die Zähne bleichen wir nicht."},{"speaker":"Dieter","gender":"m","text":"Dein eigener Termin ist einen Tag später, Monika. Was macht er bei dir?"},{"speaker":"Monika","gender":"f","text":"Ich bekomme eine Krone. Der alte Zahn hält bei mir nicht mehr."},{"speaker":"Dieter","gender":"m","text":"Lukas klagt seit Tagen über einen Schmerz hinten."},{"speaker":"Monika","gender":"f","text":"Lukas braucht eine Karies-Behandlung. Der Arzt setzt eine Plombe ein."},{"speaker":"Dieter","gender":"m","text":"Lisa ist dreizehn und der Kiefer wächst noch."},{"speaker":"Monika","gender":"f","text":"Lisa bekommt eine Zahnspange und trägt sie nachts."},{"speaker":"Dieter","gender":"m","text":"Braucht noch jemand eine Brücke?"},{"speaker":"Monika","gender":"f","text":"Nein. Eine Brücke braucht auch keiner."},{"speaker":"Dieter","gender":"m","text":"Anna hat hinten links keine Ruhe mehr."},{"speaker":"Monika","gender":"f","text":"Anna lässt den Weisheitszahn ziehen. Der Termin ist früh am Freitag."},{"speaker":"Dieter","gender":"m","text":"Ich rufe die Praxis an und bestätige jeden Termin."},{"speaker":"Monika","gender":"f","text":"Danke. Die Karten lege ich später zu den Ausweisen."}],"options":[{"letter":"a","text":"Zähne bleichen"},{"letter":"b","text":"Zahnreinigung"},{"letter":"c","text":"Krone bekommen"},{"letter":"d","text":"Weisheitszahn ziehen lassen"},{"letter":"e","text":"Brücke bekommen"},{"letter":"f","text":"Karies-Behandlung / Plombe"},{"letter":"g","text":"Implantat einsetzen"},{"letter":"h","text":"Kontrolltermin ohne Behandlung"},{"letter":"i","text":"Zahnspange bekommen"}],"items":[{"person":"Dieter","correct":"b"},{"person":"Monika","correct":"c"},{"person":"Lukas","correct":"f"},{"person":"Lisa","correct":"i"},{"person":"Anna","correct":"d"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Zahnarzt","gender":"m","text":"Guten Tag, welcher Zahn tut weh?"},{"speaker":"Patient","gender":"m","text":"Hier oben rechts, schon seit einer Woche, es tut richtig weh."},{"speaker":"Zahnarzt","gender":"m","text":"Lassen Sie mich schauen, ah, eine Karies. Sie brauchen eine Plombe, wir können das heute machen, oder nächste Woche, oder in einem Monat."},{"speaker":"Patient","gender":"m","text":"Heute schon möglich? Nächste Woche habe ich keine Zeit, und in einem Monat ist zu spät."},{"speaker":"Zahnarzt","gender":"m","text":"Heute haben wir Zeit, eine halbe Stunde reicht, dann machen wir die Plombe heute."}],"q":"Wann wird die Plombe gemacht?","opts":["Nächste Woche.","Heute.","In einem Monat."],"correct":1},{"lines":[{"speaker":"Helferin","gender":"f","text":"Guten Tag, möchten Sie eine Betäubung? Bei einer Krone ist das wichtig."},{"speaker":"Patientin","gender":"f","text":"Ich habe Angst vor Spritzen. Geht es ohne Betäubung? Oder verschieben wir den Termin?"},{"speaker":"Helferin","gender":"f","text":"Bei einer Krone ist Betäubung empfohlen. Ohne tut es sehr weh. Den Termin müssen Sie nicht verschieben."},{"speaker":"Patientin","gender":"f","text":"Okay, dann nehme ich die Betäubung mit Spritze. Aber bitte langsam, ich habe wirklich Angst."},{"speaker":"Helferin","gender":"f","text":"Kein Problem, ich mache das ruhig und erkläre jeden Schritt."}],"q":"Was macht die Patientin?","opts":["Sie nimmt keine Betäubung.","Sie verschiebt den Termin.","Sie nimmt Betäubung mit Spritze."],"correct":2},{"lines":[{"speaker":"Sekretärin","gender":"f","text":"Guten Tag, Ihre Versicherung übernimmt 80 Prozent der Kosten für die Behandlung."},{"speaker":"Patient","gender":"m","text":"Und der Rest? Zahle ich 20 Prozent selbst, oder zahle ich nichts?"},{"speaker":"Sekretärin","gender":"f","text":"20 Prozent zahlen Sie selbst, das wären 120 Euro. Nichts zahlen geht leider nicht."},{"speaker":"Patient","gender":"m","text":"Okay, zahle ich das heute oder per Rechnung?"},{"speaker":"Sekretärin","gender":"f","text":"Per Rechnung, die kommt in zwei Wochen. 80 Prozent zahlt die Versicherung direkt."}],"q":"Wie viel zahlt der Patient selbst?","opts":["80 Prozent.","Nichts.","20 Prozent."],"correct":2},{"lines":[{"speaker":"Mutter","gender":"f","text":"Guten Tag, mein Sohn braucht eine Zahnspange. Ist das jetzt genau richtig?"},{"speaker":"Zahnarzt","gender":"m","text":"Wie alt ist er denn?"},{"speaker":"Mutter","gender":"f","text":"Er ist 9 Jahre alt, manche sagen, mit 9 ist es zu spät, andere sagen früh."},{"speaker":"Zahnarzt","gender":"m","text":"Mit 9 ist es etwas früh, aber nicht zu spät. Genau richtig wäre oft mit 11 oder 12."},{"speaker":"Mutter","gender":"f","text":"Verstehe, können Sie trotzdem heute schauen?"},{"speaker":"Zahnarzt","gender":"m","text":"Ja, lass uns trotzdem schauen, dann wissen wir mehr."}],"q":"Was sagt der Zahnarzt?","opts":["Es ist etwas früh.","Es ist genau richtig.","Es ist zu spät."],"correct":0},{"lines":[{"speaker":"Patient","gender":"m","text":"Was empfehlen Sie für die Zahnpflege zu Hause?"},{"speaker":"Zahnärztin","gender":"f","text":"Zweimal täglich putzen, und auch Zahnseide jeden Tag. Das ist sehr wichtig."},{"speaker":"Patient","gender":"m","text":"Wie oft soll ich zur Kontrolle kommen? Alle 3 Monate, oder alle 6 Monate, oder nur einmal im Jahr?"},{"speaker":"Zahnärztin","gender":"f","text":"Alle 6 Monate zur Kontrolle, einmal im Jahr machen wir eine professionelle Reinigung. Alle 3 Monate ist zu oft, wenn die Zähne gesund sind."},{"speaker":"Patient","gender":"m","text":"Gut, dann alle 6 Monate, danke."}],"q":"Wie oft Kontrolle?","opts":["Alle 3 Monate.","Alle 6 Monate.","Einmal im Jahr."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Dr. Schmidt, einem Zahnarzt. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Dr. Schmidt, Sie sind seit 25 Jahren Zahnarzt. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Schmidt","gender":"m","text":"Mein Vater war auch Zahnarzt. Als Kind habe ich oft in seiner Praxis geholfen — Werkzeug säubern, beobachten. So bin ich darin aufgewachsen. Eigentlich wollte ich auch mal Chirurg werden, aber Zahnarzt ist eine schöne Mischung — präzise Arbeit und Patientenkontakt."},{"speaker":"Reporter","gender":"m","text":"Haben viele Patienten Angst vor Ihnen?"},{"speaker":"Schmidt","gender":"m","text":"Ja, das ist sehr häufig. Etwa 30 Prozent meiner Patienten haben Angst. Ich versuche immer, ruhig zu bleiben und alles zu erklären. Manchmal hilft auch Musik im Hintergrund. Spritzen sind das größte Problem — viele haben mehr Angst vor der Spritze als vor dem Bohrer."},{"speaker":"Reporter","gender":"m","text":"Was sind häufige Probleme bei Patienten?"},{"speaker":"Schmidt","gender":"m","text":"Karies, definitiv die Nummer eins. Zu viel Zucker, zu wenig Putzen. Auch Zahnfleischprobleme bei älteren Patienten. Echte Notfälle wie ausgeschlagene Zähne sind selten — meistens bei Sportunfällen oder Stürzen."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie selbst für Ihre Zähne?"},{"speaker":"Schmidt","gender":"m","text":"Drei Mal täglich putzen, Zahnseide. Mein Kollege macht meine Kontrollen — zu meinen eigenen Zähnen kann ich ja nicht selber schauen. Süßes esse ich selten, das hilft auch."},{"speaker":"Reporter","gender":"m","text":"Würden Sie diesen Beruf nochmal wählen?"},{"speaker":"Schmidt","gender":"m","text":"Absolut. Auch nach 25 Jahren freue ich mich auf jeden Tag. Die Augen eines Patienten, der ohne Schmerzen aus meiner Praxis geht — das ist die schönste Belohnung."}],"items":[{"q":"Sein Vater war auch Zahnarzt.","correct":"ja"},{"q":"Etwa 30% der Patienten haben Angst.","correct":"ja"},{"q":"Ausgeschlagene Zähne sind sehr häufig.","correct":"nein"},{"q":"Er macht seine Zahn-Kontrollen selbst.","correct":"nein"},{"q":"Er würde diesen Beruf nicht nochmal wählen.","correct":"nein"}]}]};
